DROP TABLE IF EXISTS `ai_kb_chunk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_kb_chunk` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `course_id` bigint NOT NULL,
  `offering_id` bigint DEFAULT NULL,
  `teaching_class_id` bigint DEFAULT NULL,
  `source_type` varchar(20) NOT NULL,
  `source_id` bigint NOT NULL,
  `doc_name` varchar(200) NOT NULL,
  `section_no` int NOT NULL COMMENT '文档内第几段（从 1 开始）',
  `content` text NOT NULL,
  `char_len` int NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_course_source` (`course_id`,`source_type`,`source_id`),
  FULLTEXT KEY `ft_content` (`content`) /*!50100 WITH PARSER `ngram` */ 
) ENGINE=InnoDB AUTO_INCREMENT=900117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库分块（ngram 全文索引）';
/*!40101 SET character_set_client = @saved_cs_client */;

