-- Table structure for table `ai_question_draft`
--

DROP TABLE IF EXISTS `ai_question_draft`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_question_draft` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `offering_id` bigint NOT NULL,
  `lesson_id` bigint DEFAULT NULL,
  `resource_ids` varchar(300) DEFAULT NULL COMMENT '来源资料ID，逗号分隔',
  `q_type` varchar(20) NOT NULL COMMENT 'SINGLE / MULTI / JUDGE / BLANK / SHORT',
  `difficulty` varchar(10) DEFAULT NULL COMMENT 'easy / medium / hard',
  `stem` text NOT NULL,
  `options_json` json DEFAULT NULL,
  `answer_json` json DEFAULT NULL,
  `analysis` text,
  `group_name` varchar(100) DEFAULT NULL COMMENT '沿用试卷分组名，替代知识点',
  `source_pages` varchar(100) DEFAULT NULL COMMENT '依据页码，如 3,4',
  `quality_json` json DEFAULT NULL COMMENT '五道闸门结果',
  `full_score` decimal(6,2) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT / APPROVED / REJECTED / ADOPTED',
  `model` varchar(50) DEFAULT NULL,
  `prompt_version` varchar(20) DEFAULT NULL,
  `run_id` bigint DEFAULT NULL,
  `tokens` int DEFAULT NULL,
  `cost` decimal(10,6) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `reviewer_id` bigint DEFAULT NULL,
  `review_time` datetime DEFAULT NULL,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_offering_status` (`offering_id`,`status`),
