DROP TABLE IF EXISTS `course_group`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `course_group` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '课程组ID',
  `course_id` bigint NOT NULL COMMENT '课程ID（科目）',
  `term_id` bigint NOT NULL COMMENT '学期ID',
  `level` varchar(10) NOT NULL DEFAULT 'L2' COMMENT '构成层级：L1只填三项总分/L2平时拆项(默认)/L3自定义项(实验、三四级项目等)',
  `level_request` varchar(10) DEFAULT NULL COMMENT '申请的层级（老师发起升级时填写）',
  `level_request_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '升级申请状态：NONE无/PENDING待教务审批/APPROVED已批准/REJECTED已驳回',
  `level_request_by` bigint DEFAULT NULL COMMENT '申请人（教师ID）',
  `level_request_time` datetime DEFAULT NULL COMMENT '申请时间',
  `level_request_reason` varchar(200) DEFAULT NULL COMMENT '申请理由（如：本课含 5 次实验 + 三级项目）',
  `level_approve_by` bigint DEFAULT NULL COMMENT '审批人（教务ID）',
  `level_approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `level_approve_note` varchar(200) DEFAULT NULL COMMENT '审批意见',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE/CLOSED',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_term` (`course_id`,`term_id`),
  KEY `idx_term` (`term_id`),
  KEY `idx_level_request` (`level_request_status`)
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='课程组表（课程×学期，无组长）';
