  KEY `idx_status` (`status`,`is_void`)
) ENGINE=InnoDB AUTO_INCREMENT=600097 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='课次表（一次课一行；点名与覆盖率的基础）';
