INSERT INTO `question` VALUES (90001,9001,1,'SHORT','求极限 lim(x→0) sin(3x)/x，并说明使用的等价无穷小。',NULL,'{\"ref\": \"sin(3x)~3x，故极限为 3\", \"rubric\": [\"等价无穷小\", \"极限结果\"]}','sin(3x)~3x，故极限为 3',10.00,'一、简答题',1,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90002,9001,2,'SHORT','说明导数与函数单调性的关系，并给出一个单调递增的判定条件。',NULL,'{\"ref\": \"f\'(x)>0 则严格递增；f\'(x)<0 则递减\", \"rubric\": [\"导数符号\", \"单调性结论\"]}','f\'(x)>0 则严格递增；f\'(x)<0 则递减',10.00,'一、简答题',2,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90003,9001,3,'SHORT','计算定积分 ∫₀¹ (2x+1) dx，并写出牛顿-莱布尼茨公式。',NULL,'{\"ref\": \"原函数 x²+x，结果 2；∫ₐᵇ f=F(b)−F(a)\", \"rubric\": [\"原函数\", \"公式\", \"结果\"]}','原函数 x²+x，结果 2；∫ₐᵇ f=F(b)−F(a)',10.00,'一、简答题',3,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90004,9001,4,'SHORT','判断级数 Σ 1/n² 的敛散性，并说明依据。',NULL,'{\"ref\": \"p=2>1 的 p 级数收敛\", \"rubric\": [\"p 级数\", \"收敛结论\"]}','p=2>1 的 p 级数收敛',10.00,'一、简答题',4,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90005,9001,5,'SHORT','简述矩阵可逆的两种判定方法。',NULL,'{\"ref\": \"行列式非零；秩等于阶数\", \"rubric\": [\"行列式\", \"秩\"]}','行列式非零；秩等于阶数',10.00,'一、简答题',5,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90011,9002,1,'SHORT','简述顺序表与链表的优缺点，并说明各自适用场景。',NULL,'{\"ref\": \"顺序表随机访问快、插入删除慢；链表相反\", \"rubric\": [\"访问复杂度\", \"插入删除\", \"适用场景\"]}','顺序表随机访问快、插入删除慢；链表相反',10.00,'一、简答题',1,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90012,9002,2,'SHORT','写出二叉树前序遍历的递归定义，并给出一个例子。',NULL,'{\"ref\": \"根→左→右；例子略\", \"rubric\": [\"遍历顺序\", \"递归\", \"例子\"]}','根→左→右；例子略',10.00,'一、简答题',2,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90013,9002,3,'SHORT','说明栈与队列的区别，并各举一个应用。',NULL,'{\"ref\": \"栈 LIFO（表达式求值）；队列 FIFO（BFS）\", \"rubric\": [\"LIFO/FIFO\", \"应用\"]}','栈 LIFO（表达式求值）；队列 FIFO（BFS）',10.00,'一、简答题',3,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90014,9002,4,'SHORT','简述哈希表冲突处理的两种方法。',NULL,'{\"ref\": \"开放定址法；链地址法\", \"rubric\": [\"开放定址\", \"链地址\"]}','开放定址法；链地址法',10.00,'一、简答题',4,'2026-09-28 09:00:00','2026-09-28 09:00:00'),(90015,9002,5,'SHORT','分析快速排序平均时间复杂度及最坏情况。',NULL,'{\"ref\": \"平均 O(n log n)，最坏 O(n²)\", \"rubric\": [\"平均\", \"最坏\", \"原因\"]}','平均 O(n log n)，最坏 O(n²)',10.00,'一、简答题',5,'2026-09-28 09:00:00','2026-09-28 09:00:00');
/*!40000 ALTER TABLE `question` ENABLE KEYS */;
