INSERT INTO `risk_engine_config` VALUES (1,'v2.0.0','2026-10-23 19:18:30',0,1,1,0,'{\"normal\": {\"score\": 0.3, \"homework\": 0.25, \"attendance\": 0.3, \"subjective\": 0.15}, \"freshman\": {\"score\": 0.25, \"homework\": 0.3, \"attendance\": 0.4, \"subjective\": 0.05}}',1,1,75.0,60.0,40.0,0.333,4,5,0.300,5,0.500,10,40.0,3,14,2.0,1.0,1.0,3,100.0,60,30,20.0,0.400,'通道C先关闭（Δ 需积累数据后启用）；其余为四轮讨论已确认口径',NULL,'2026-10-17 21:09:46',1,'2026-10-30 20:42:45',1.10,0.90,5.00,1.05,1.20,1.05,1.10,1.05,0.95),(8,'v2.1.0','2026-10-30 20:42:45',1,1,1,1,NULL,1,1,75.0,60.0,40.0,0.333,4,5,0.300,5,0.500,10,40.0,3,14,2.0,1.0,1.0,3,100.0,60,30,20.0,0.400,'v2.1.0：过程分口径 + 绝对达标判定 + C 通道（考试课/考查课、历史挂科率、教师风格、个人前科）',NULL,'2026-10-30 20:42:21',1,'2026-10-30 20:42:45',1.10,0.90,5.00,1.05,1.20,1.05,1.10,1.05,0.95);
