  `account_id` bigint DEFAULT NULL COMMENT '账号ID',
  `teacher_no` varchar(20) NOT NULL COMMENT '工号',
  `teacher_name` varchar(30) NOT NULL COMMENT '姓名',
  `gender` tinyint(1) DEFAULT NULL COMMENT '性别：1男 2女 0未知',
  `title` varchar(30) DEFAULT NULL COMMENT '职称：教授/副教授/讲师/助教/未定级（展示用；Δ 收缩由样本量自动决定，不依赖职称）',
  `college_name` varchar(50) DEFAULT NULL COMMENT '所属学院/教研室',
  `phone` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE/LEFT离职',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_teacher_no` (`teacher_no`),
  KEY `idx_account` (`account_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='教师表';
