DROP TABLE IF EXISTS `teacher_style`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teacher_style` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `teacher_id` bigint NOT NULL COMMENT '教师ID',
  `offering_id` bigint NOT NULL COMMENT '开课ID（Δ 是"该教师在该课"的尺度）',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `term_id` bigint NOT NULL COMMENT '学期ID',
  `scheme_item_id` bigint DEFAULT NULL COMMENT '评分项ID（分项级 Δ；整体级为空）',
  `item_code` varchar(30) NOT NULL DEFAULT 'OVERALL' COMMENT '评分项编码；整体级固定 OVERALL',
  `raw_delta` decimal(5,2) DEFAULT NULL COMMENT '未收缩的原始 Δ（班 vs 课程平均）',
  `delta` decimal(5,2) DEFAULT NULL COMMENT '收缩后的 Δ̂ = raw_delta × λ（实际用于折算）',
  `shrink_lambda` decimal(4,3) DEFAULT NULL COMMENT '收缩系数 λ = n/(n+k)，k 见 risk_engine_config',
  `sample_size` int NOT NULL DEFAULT '0' COMMENT '参与估计的样本量（学生数）',
  `std_dev` decimal(5,2) DEFAULT NULL COMMENT '样本标准差（异常检测用）',
  `fused` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否熔断：1停用该 Δ（|Δ| 超阈值，等教务复核）',
  `fuse_reason` varchar(200) DEFAULT NULL COMMENT '熔断原因/复核说明',
  `review_by` bigint DEFAULT NULL COMMENT '复核人（教务ID）',
  `review_time` datetime DEFAULT NULL COMMENT '复核时间',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE可用/INSUFFICIENT样本不足/FUSED已熔断/REVIEWED复核通过',
  `engine_version` varchar(20) DEFAULT NULL,
  `calc_time` datetime DEFAULT NULL COMMENT '估计时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_teacher_offering_item` (`teacher_id`,`offering_id`,`item_code`),
  KEY `idx_offering` (`offering_id`),
  KEY `idx_course_term` (`course_id`,`term_id`),
  KEY `idx_status` (`status`,`fused`)
) ENGINE=InnoDB AUTO_INCREMENT=6013 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='教师尺度Δ表（分项级，含收缩与熔断）';
/*!40101 SET character_set_client = @saved_cs_client */;

