  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_term_code` (`term_code`),
  KEY `idx_is_current` (`is_current`),
  KEY `idx_year_no` (`school_year`,`term_no`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='学期表（全库时间轴）';
